mapper.select:
SELECT COUNT(*) > 0
FROM habit_history
WHERE user_habit_id = #{userHabitId} AND check_date = #{checkDate}

mapper.update:
UPDATE user_habit SET name = #{name}, category_user_id = #{categoryUserId}, color = #{color}, frequency = #{frequency},
start_date = #{startDate},
is_public = CASE WHEN #{isPublic} THEN '1' ELSE '0' END, updated_at = NOW() WHERE id = #{id}

mapper.select:
SELECT hh.check_date AS date, COUNT(*) AS count
FROM habit_history hh
JOIN user_habit uh ON hh.user_habit_id = uh.id
WHERE uh.member_id = #{memberId}
AND YEAR(hh.check_date) = #{year}
AND MONTH(hh.check_date) = #{month}
GROUP BY hh.check_date
ORDER BY hh.check_date ASC
